"""Accepted native Mapping containers must not bypass numeric validation."""
from collections import UserDict
from types import MappingProxyType

import pytest
from deepviz.models import ChartSpec
from pydantic import ValidationError

FACTORIES = [UserDict, MappingProxyType]
NUMBERS = {"version": 1, "max_points": 2000, "width": 900, "height": 520, "columns": 2}


@pytest.mark.parametrize("factory", FACTORIES)
@pytest.mark.parametrize("field", NUMBERS)
@pytest.mark.parametrize("invalid", ["numeric-string", True, False])
def test_supported_mappings_reject_the_same_numeric_coercions(factory, field, invalid):
    value = str(NUMBERS[field]) if invalid == "numeric-string" else invalid
    original = {field: value}
    payload = factory(original)
    with pytest.raises(ValidationError, match=f"{field} must be a JSON number"):
        ChartSpec.model_validate(payload)
    assert dict(payload) == original


@pytest.mark.parametrize("factory", FACTORIES)
@pytest.mark.parametrize("values", [{}, {key: float(value) for key, value in NUMBERS.items()}])
def test_supported_mappings_preserve_defaults_and_integral_numbers(factory, values):
    payload = factory(values)
    parsed = ChartSpec.model_validate(payload)
    assert {key: getattr(parsed, key) for key in NUMBERS} == NUMBERS
    assert all(type(getattr(parsed, key)) is int for key in NUMBERS)
    assert dict(payload) == values


@pytest.mark.parametrize("factory", FACTORIES)
@pytest.mark.parametrize("invalid", ["900", True, False])
def test_nested_mapping_children_cannot_bypass_the_numeric_guard(factory, invalid):
    with pytest.raises(ValidationError, match="width must be a JSON number"):
        ChartSpec.model_validate({"kind": "dashboard", "charts": [factory({"width": invalid})]})


@pytest.mark.parametrize("factory", FACTORIES)
def test_nested_integral_mapping_children_remain_valid(factory):
    parsed = ChartSpec.model_validate({"kind": "dashboard", "charts": [factory({"width": 900.0})]})
    assert parsed.charts[0].width == 900

"""JSON Schema agreement for the numeric runtime fix, not toolkit integration."""
import json
from pathlib import Path

import deepviz.models as models
import pytest
from deepviz.models import ChartSpec
from jsonschema import Draft202012Validator
from pydantic import ValidationError

ROOT = Path(__file__).resolve().parents[1]


def test_model_import_is_this_checkout_not_an_installed_sibling():
    assert Path(models.__file__).resolve() == ROOT / "python/deepviz/src/deepviz/models.py"


def test_published_schema_is_the_actual_model_export():
    published = json.loads((ROOT / "schemas/chart-spec.schema.json").read_text(encoding="utf-8"))
    assert published == ChartSpec.model_json_schema()
    Draft202012Validator.check_schema(published)


@pytest.mark.parametrize("field,minimum,maximum,default", [
    ("version", 1, 1, 1),
    ("max_points", 10, 100000, 2000),
    ("width", 240, 4096, 900),
    ("height", 200, 4096, 520),
    ("columns", 1, 6, 2),
])
def test_numeric_json_types_and_bounds_agree(field, minimum, maximum, default):
    schema = Draft202012Validator(ChartSpec.model_json_schema())
    for value, expected in [
        (minimum, True), (maximum, True), (default, True), (float(default), True),
        (True, False), (False, False), (str(default), False), (None, False),
        (minimum - 1, False), (maximum + 1, False), (default + 0.5, False),
    ]:
        payload = {field: value}
        assert schema.is_valid(payload) is expected
        try:
            parsed = ChartSpec.model_validate_json(json.dumps(payload))
        except ValidationError:
            assert not expected, (field, value)
        else:
            assert expected, (field, value)
            assert schema.is_valid(parsed.model_dump(mode="json"))


@pytest.mark.parametrize("width,valid", [(900.0, True), ("900", False), (True, False)])
def test_numeric_child_validation_is_not_bypassed_by_dashboard(width, valid):
    payload = {"kind": "dashboard", "charts": [{"width": width}]}
    schema = Draft202012Validator(ChartSpec.model_json_schema())
    assert schema.is_valid(payload) is valid
    if valid:
        spec = ChartSpec.model_validate_json(json.dumps(payload))
        assert spec.charts[0].width == 900
    else:
        with pytest.raises(ValidationError):
            ChartSpec.model_validate_json(json.dumps(payload))
